mapper.select:
select m.id,m.music_name,m.album_id,m.musician_id,m.duration,m.cover_url,m.is_vip,m.status, u.username as musicianName, a.album_name, l.updated_time from music as m left join user as u on m.musician_id=u.id left join album as a on m.album_id=a.id left join like_record l on m.id=l.target_id where l.user_id=#{userId} and l.is_canceled=0
and m.id < #{lastId}
order by l.created_time desc limit #{pageSize}

select count(1)
from
    like_record
where
    user_id=#{userId}
and id < #{lastId}
